    const MOD = 1000000007n;
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const pow2 = new Array(n);
    pow2[0] = 1n;
    for (let i = 1; i < n; i++) {
        pow2[i] = (pow2[i - 1] * 2n) % MOD;
    }
    let left = 0, right = n - 1, ans = 0n;
    while (left <= right) {
